{"tool": "write", "args": {"path": "src/validate_outputs.py", "content": "#!/usr/bin/env python3
"""Validation script for pipeline outputs in Task 14."""

import csv
import json
import os
from pathlib import Path


def check_csv_exists(filepath):
    """Check if a CSV file exists and is non-empty."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"
    if path.stat().st_size == 0:
        return False, f"Empty file: {filepath}"
    return True, f"File exists: {filepath}"


def check_csv_columns(filepath, required_columns):
    """Check if CSV file has required columns."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        columns = set(reader.fieldnames) if reader.fieldnames else set()
        missing = set(required_columns) - columns
        if missing:
            return False, f"Missing columns in {filepath}: {missing}"
        return True, f"Has required columns: {required_columns}"


def check_csv_row_count(filepath, min_rows):
    """Check if CSV file has at least min_rows data rows."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        rows = sum(1 for _ in csv.reader(f)) - 1  # Subtract header
    if rows < min_rows:
        return False, f"Too few rows in {filepath}: {rows} < {min_rows}"
    return True, f"Has {rows} data rows"


def check_csv_no_empty_values(filepath):
    """Check if CSV file has no completely empty rows."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if not header:
            return False, f"Empty file: {filepath}"

        empty_rows = 0
        for row in reader:
            if not any(cell.strip() for cell in row):
                empty_rows += 1

        if empty_rows > 0:
            return False, f"Found {empty_rows} empty rows in {filepath}"
        return True, "No empty data rows"


def check_accessibility_scores(filepath):
    """Validate accessibility scores CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check accessibility_score column exists
    if 'accessibility_score' not in reader.fieldnames:
        return False, f"Missing accessibility_score column: {filepath}"

    # Check scores are valid (between 0 and 1)
    for row in rows:
        try:
            score = float(row['accessibility_score'])
            if not (0 <= score <= 1):
                return False, f"Invalid accessibility_score {score} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid accessibility_score value in {filepath}"

    return True, f"Valid {len(rows)} accessibility records"


def check_clean_stops(filepath):
    """Validate cleaned GTFS stops CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check required columns
    required = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
    if not all(col in reader.fieldnames for col in required):
        return False, f"Missing required columns: {required}"

    # Check lat/lon are valid numbers
    for row in rows:
        try:
            lat = float(row['stop_lat'])
            lon = float(row['stop_lon'])
            if not (-90 <= lat <= 90):
                return False, f"Invalid latitude {lat} in {filepath}"
            if not (-180 <= lon <= 180):
                return False, f"Invalid longitude {lon} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid coordinate in {filepath}"

    return True, f"Valid {len(rows)} stop records"


def check_clean_pois(filepath):
    """Validate cleaned POIs CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check required columns
    required = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
    missing = [col for col in required if col not in reader.fieldnames]
    if missing:
        return False, f"Missing required columns: {missing}"

    # Check lat/lon are valid numbers
    for row in rows:
        try:
            lat = float(row['latitude'])
            lon = float(row['longitude'])
            if not (-90 <= lat <= 90):
                return False, f"Invalid latitude {lat} in {filepath}"
            if not (-180 <= lon <= 180):
                return False, f"Invalid longitude {lon} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid coordinate in {filepath}"

    return True, f"Valid {len(rows)} POI records"


def check_city_clusters(filepath):
    """Validate city clusters CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check required columns
    required = ['city_id', 'city_name', 'year', 'cluster_id']
    missing = [col for col in required if col not in reader.fieldnames]
    if missing:
        return False, f"Missing required columns: {missing}"

    # Check year is valid
    for row in rows:
        try:
            year = int(row['year'])
            if year < 2020 or year > 2025:
                return False, f"Invalid year {year} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid year value in {filepath}"

    return True, f"Valid {len(rows)} city cluster records"


def check_city_indicator_matrix(filepath):
    """Validate city indicator matrix CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check required columns
    required = ['city_id', 'city_name', 'year']
    missing = [col for col in required if col not in reader.fieldnames]
    if missing:
        return False, f"Missing required columns: {missing}"

    # Check year is valid
    for row in rows:
        try:
            year = int(row['year'])
            if year < 2020 or year > 2025:
                return False, f"Invalid year {year} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid year value in {filepath}"

    return True, f"Valid {len(rows)} city indicator records"


def main():
    """Run all validation checks."""
    base_dir = Path.cwd()
    outputs_dir = base_dir / 'outputs'
    src_dir = base_dir / 'src'

    # Define output files to validate
    checks = [
        {
            'name': 'cleaned_gtfs_stops',
            'file': outputs_dir / 't05_clean_stops.csv',
            'checks': [
                {'func': check_csv_exists, 'msg': 'exists'},
                {'func': check_csv_columns, 'msg': 'required_columns', 'args': ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']},
                {'func': check_csv_row_count, 'msg': 'row_count', 'args': 1},
                {'func': check_csv_no_empty_values, 'msg': 'no_empty_rows'},
            ]
        },
        {
            'name': 'cleaned_pois',
            'file': outputs_dir / 't08_pois_clean.csv',
            'checks': [
                {'func': check_csv_exists, 'msg': 'exists'},
                {'func': check_csv_columns, 'msg': 'required_columns', 'args': ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']},
                {'func': check_csv_row_count, 'msg': 'row_count', 'args': 1},
                {'func': check_csv_no_empty_values, 'msg': 'no_empty_rows'},
            ]
        },
        {
            'name': 'accessibility_scores',
            'file': outputs_dir / 't10_accessibility_scores.csv',
            'checks': [
                {'func': check_csv_exists, 'msg': 'exists'},
                {'func': check_csv_columns, 'msg': 'required_columns', 'args': ['qid', 'label', 'poi_type', 'distance_m', 'n_departures', 'n_routes', 'accessibility_score']},
                {'func': check_csv_row_count, 'msg': 'row_count', 'args': 1},
                {'func': check_accessibility_scores, 'msg': 'valid_scores'},
            ]
        },
        {
            'name': 'city_clusters',
            'file': outputs_dir / 't13_city_clusters.csv',
            'checks': [
                {'func': check_csv_exists, 'msg': 'exists'},
                {'func': check_csv_columns, 'msg': 'required_columns', 'args': ['city_id', 'city_name', 'year', 'cluster_id']},
                {'func': check_csv_row_count, 'msg': 'row_count', 'args': 1},
                {'func': check_city_clusters, 'msg': 'valid_years'},
            ]
        },
        {
            'name': 'city_indicator_matrix',
            'file': outputs_dir / 't11_city_indicator_matrix.csv',
            'checks': [
                {'func': check_csv_exists, 'msg': 'exists'},
                {'func': check_csv_columns, 'msg': 'required_columns', 'args': ['city_id', 'city_name', 'year']},
                {'func': check_csv_row_count, 'msg': 'row_count', 'args': 1},
                {'func': check_city_indicator_matrix, 'msg': 'valid_years'},
            ]
        },
    ]

    results = []

    for check_def in checks:
        check_name = check_def['name']
        filepath = check_def['file']

        for sub_check in check_def['checks']:
            func_name = sub_check['msg']
            args = sub_check.get('args', ())

            try:
                func = getattr(__import__('validate_outputs', fromlist=[func_name]), func_name)
                passed, message = func(filepath, *args)
                results.append({
                    'check_name': f"{check_name} - {func_name}",
                    'passed': passed,
                    'message': message
                })
            except Exception as e:
                results.append({
                    'check_name': f"{check_name} - {func_name}",
                    'passed': False,
                    'message': f"Error: {str(e)}"
                })

    # Write results to JSON
    output_file = outputs_dir / 't14_validation_summary.json'
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Validation complete. Results written to {output_file}")
    print(f"Total checks: {len(results)}")
    print(f"Passed: {sum(1 for r in results if r['passed'])}")
    print(f"Failed: {sum(1 for r in results if not r['passed'])}")

    return results


if __name__ == '__main__':
    main()
