"""Validation script for pipeline outputs in Task 14."""

import csv
import json
import os
from pathlib import Path


def check_csv_exists(filepath):
    """Check if a CSV file exists and is non-empty."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"
    if path.stat().st_size == 0:
        return False, f"Empty file: {filepath}"
    return True, f"File exists: {filepath}"


def check_csv_columns(filepath, required_columns):
    """Check if CSV file has required columns."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        columns = set(reader.fieldnames) if reader.fieldnames else set()
        missing = set(required_columns) - columns
        if missing:
            return False, f"Missing columns in {filepath}: {missing}"
        return True, f"Has required columns: {required_columns}"


def check_csv_row_count(filepath, min_rows):
    """Check if CSV file has at least min_rows data rows."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        rows = sum(1 for _ in csv.reader(f)) - 1  # Subtract header
    if rows < min_rows:
        return False, f"Too few rows in {filepath}: {rows} < {min_rows}"
    return True, f"Has {rows} data rows"


def check_csv_no_empty_values(filepath):
    """Check if CSV file has no completely empty rows."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if not header:
            return False, f"Empty file: {filepath}"

        empty_rows = 0
        for row in reader:
            if not any(cell.strip() for cell in row):
                empty_rows += 1

        if empty_rows > 0:
            return False, f"Found {empty_rows} empty rows in {filepath}"
        return True, "No empty data rows"


def check_accessibility_scores(filepath):
    """Validate accessibility scores CSV."""
    path = Path(filepath)
    if not path.exists():
        return False, f"File not found: {filepath}"

    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return False, f"Empty file: {filepath}"

    # Check accessibility_score column exists
    if 'accessibility_score' not in reader.fieldnames:
        return False, f"Missing accessibility_score column: {filepath}"

    # Check scores are valid (between 0 and 1)
    for row in rows:
        try:
            score = float(row['accessibility_score'])
            if not (0 <= score <= 1):
                return False, f"Invalid accessibility_score {score} in {filepath}"
        except (ValueError, KeyError):
            return False, f"Invalid accessibility_score value in {filepath}"

    return True, f"Valid {len(rows)} accessibility records"


